_tables = {}


def _table(lang):
	if lang not in _tables:
		import json
		import os
		try:
			with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "i18n", lang + ".json"), "rb") as f:
				_tables[lang] = json.loads(f.read().decode("utf-8"))
		except Exception as e:
			print("[MohammedSkin] language %s: %s" % (lang, e))
			_tables[lang] = {}
	return _tables[lang]


def tr(lang, text):
	if lang == "ar":
		return AR.get(text, text)
	if lang == "en" or not lang:
		return text
	return _table(lang).get(text, text)
